package com.profa.school;import jakarta.persistence.*;import java.util.*;@Entity @Table(name="school_profiles") public class SchoolProfile{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false,unique=true)UUID userId;String name;String city;String district;String address;String description;String logoUrl;String website;String phone;Integer employeeCount;public UUID getId(){return id;}public UUID getUserId(){return userId;}public void setUserId(UUID v){userId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getCity(){return city;}public void setCity(String v){city=v;}public String getDistrict(){return district;}public void setDistrict(String v){district=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getLogoUrl(){return logoUrl;}public void setLogoUrl(String v){logoUrl=v;}public String getWebsite(){return website;}public void setWebsite(String v){website=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public Integer getEmployeeCount(){return employeeCount;}public void setEmployeeCount(Integer v){employeeCount=v;}}
